package cn.sixnine.filmlog;
import android.app.Instrumentation;
import android.os.Bundle;
import android.graphics.Bitmap;
import android.content.Context;
import java.io.*;
import java.util.*;
import org.json.*;

/** Isolated atomic camera-reference, schema migration, and archive checks. */
public final class ReferencePhotosInstrumentation extends Instrumentation {
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private String record(Context c,LogStore logs,String token,String roll,long tap)throws Exception{return ReferencePhotos.record(c,logs,token,roll,tap,-10,480,"denied","8","1/125","50mm","reference","+1","");}
    private String capture(Context c)throws Exception{String token=UUID.randomUUID().toString();Bitmap image=Bitmap.createBitmap(80,60,Bitmap.Config.ARGB_8888);image.eraseColor(0xff975e31);try{ReferencePhotos.capture(c,token,image);}finally{image.recycle();}return token;}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){waitForIdleSync();Bundle result=new Bundle();try{
        Context c=getTargetContext();check(c.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolation");c.deleteDatabase("film-log.db");LogStore logs=new LogStore(c);String roll=logs.addRoll("Reference","Gold","Camera",200,36);ScanStore scans=new ScanStore(c,logs);
        // Emulate the actual previous schema, keeping all old data intact.
        String old=logs.insert(roll,20000,-10,480,"denied","5.6","1/60","","old","","");android.database.sqlite.SQLiteDatabase fixture=logs.getWritableDatabase();for(String table:new String[]{"catalog_entries","film_batches","roll_details","stock_history"}){try(android.database.Cursor rows=fixture.rawQuery("SELECT COUNT(*) FROM "+table,null)){rows.moveToFirst();check(rows.getInt(0)==0,"v9 fixture has no catalog rows to discard");}fixture.execSQL("DROP TABLE "+table);}CatalogStore.createTables(fixture);for(String table:new String[]{"film_stocks","reference_photos","artwork_links","exposure_presets"})fixture.execSQL("DROP TABLE "+table);fixture.setVersion(9);logs.close();logs=new LogStore(c);scans=new ScanStore(c,logs);check(logs.getReadableDatabase().getVersion()==24&&logs.shot(old).captured==10000,"v9 upgrade preserves old exposure");
        String token=capture(c),shot=record(c,logs,token,roll,100000);check(logs.shot(shot).captured==90000&&logs.shot(shot).tapped==100000&&logs.shot(shot).zone==480,"tap offset timezone");check(ReferencePhotos.forShot(logs,shot).equals(token)&&ReferencePhotos.file(c,logs,token).isFile(),"reference attachment");check(scans.list(roll).isEmpty()&&!ReferencePhotos.draft(c,token).exists(),"reference never becomes scan, draft removed");check(record(c,logs,token,roll,100000).equals(shot)&&logs.shots(roll).size()==2,"idempotent retry");
        try{record(c,logs,token,roll,100001);throw new AssertionError("changed retry accepted");}catch(IllegalArgumentException expected){}
        int frame=logs.nextFrame(roll);try{record(c,logs,UUID.randomUUID().toString(),roll,110000);throw new AssertionError("missing draft accepted");}catch(IOException expected){}check(logs.nextFrame(roll)==frame,"missing draft cannot consume frame");
        String failed=capture(c);logs.getWritableDatabase().execSQL("CREATE TRIGGER fail_reference BEFORE INSERT ON reference_photos BEGIN SELECT RAISE(ABORT,'test rollback'); END");try{record(c,logs,failed,roll,120000);throw new AssertionError("failed attachment committed");}catch(android.database.sqlite.SQLiteException expected){}check(logs.nextFrame(roll)==frame&&scans.list(roll).isEmpty()&&!scans.file(failed).exists()&&ReferencePhotos.draft(c,failed).exists(),"file and exposure rollback; retry keeps draft");logs.getWritableDatabase().execSQL("DROP TRIGGER fail_reference");String retried=record(c,logs,failed,roll,120000);check(logs.shot(retried).frame==frame,"retry no frame gap");
        String collision=capture(c);ScanStore.Scan scan;try(InputStream in=new FileInputStream(ReferencePhotos.draft(c,collision))){scan=scans.importJpeg(roll,"lab.jpg",in,collision);}long length=scans.file(collision).length();try{record(c,logs,collision,roll,130000);throw new AssertionError("scan collision accepted");}catch(IOException expected){}check(scans.file(collision).length()==length&&scans.list(roll).size()==1,"collision preserves lab scan");ReferencePhotos.discard(c,collision);
        File orphan=scans.file(UUID.randomUUID().toString());try(OutputStream out=new FileOutputStream(orphan)){out.write(1);}FilmApplication.cleanupFiles(c,logs);check(!orphan.exists()&&ReferencePhotos.file(c,logs,token).exists()&&scans.file(collision).exists(),"startup retains references and scans only");
        ByteArrayOutputStream archive=new ByteArrayOutputStream();FilmBackup.write(c,logs,archive);int before=logs.rolls().size();try(FilmBackup.Prepared prepared=FilmBackup.inspect(c,new ByteArrayInputStream(archive.toByteArray()))){check(prepared.manifest.getInt("schema")==25&&prepared.count("reference_photos")==2,"schema14 archive");FilmBackup.restore(c,logs,prepared);check(logs.rolls().size()==before*2,"append archive");int referenceCount=0;for(LogStore.Roll r:logs.rolls())for(LogStore.Shot s:logs.shots(r.id)){String ref=ReferencePhotos.forShot(logs,s.id);if(!ref.isEmpty()){check(ReferencePhotos.file(c,logs,ref).length()>0,"restored reference file");referenceCount++;}}check(referenceCount==4,"reference shot IDs remapped");JSONObject row=prepared.manifest.getJSONArray("reference_photos").getJSONObject(0);String hash=row.getString("sha256");row.put("sha256","bad");try{FilmBackup.restore(c,logs,prepared);throw new AssertionError("bad reference hash accepted");}catch(IOException expected){}row.put("sha256",hash);String fk=row.getString("shot_id");row.put("shot_id","missing");try{FilmBackup.restore(c,logs,prepared);throw new AssertionError("bad reference FK accepted");}catch(IOException expected){}row.put("shot_id",fk);check(logs.rolls().size()==before*2,"invalid archive leaves data intact");}
        logs.close();result.putString("stream","PASS: v9 migration/tap-offset-zone/reference isolation/idempotence/conflicting retry/missing draft/transaction rollback/no frame gap/scan collision/startup recovery/schema14 archive/FK remap/hash validation\n");finish(-1,result);
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));finish(0,result);}}
}
